# Google Sheets V2 (lazy import: the app can still start without gspread installed)
import json
import hashlib
import uuid

GOOGLE_SHEET_URL = "https://docs.google.com/spreadsheets/d/1vqPq4QtKuba6fg1DMfltLIfZAX4f-qJCqBAVgalwauA/edit?usp=sharing"
GOOGLE_DB_SHEETS = {
    "students": "Students",
    "assessments": "Assessments",
    "audit": "Audit_Log",
}

DB_ASSESSMENT_HEADERS = [
    "record_key", "assessment_id", "student_id", "name", "name_key",
    "class", "class_key", "level", "teacher", "course_start", "course_end",
    "exam_start", "exam_end", "assessment_type", "status",
    "attendance", "listening", "speaking", "reading", "writing",
    "overall", "grade", "weak_skills", "source_file", "version",
    "created_at", "updated_at",
]
DB_STUDENT_HEADERS = [
    "student_id", "name", "name_key", "first_seen", "last_seen",
    "current_class", "current_level", "status",
]
DB_AUDIT_HEADERS = [
    "upload_id", "timestamp", "source_file", "operator", "total",
    "new", "existing", "changed", "duplicates_in_file", "ambiguous",
]

def _gs_imports():
    try:
        import gspread
        from google.oauth2.service_account import Credentials
        return gspread, Credentials
    except ImportError as exc:
        raise RuntimeError(
            "Thiếu thư viện Google Sheets. Cài: gspread google-auth google-auth-oauthlib"
        ) from exc

def _gs_credentials(secret_value):
    gspread, Credentials = _gs_imports()
    if isinstance(secret_value, str):
        secret_value = secret_value.strip()
        try:
            secret_value = json.loads(secret_value)
        except json.JSONDecodeError as exc:
            raise ValueError("gcp_service_account_json không phải JSON hợp lệ.") from exc
    if not isinstance(secret_value, dict):
        raise ValueError("gcp_service_account_json phải là dict hoặc chuỗi JSON.")
    scopes = [
        "https://www.googleapis.com/auth/spreadsheets",
        "https://www.googleapis.com/auth/drive",
    ]
    creds = Credentials.from_service_account_info(secret_value, scopes=scopes)
    return gspread.authorize(creds)

def get_google_database(secret_value, spreadsheet_url=GOOGLE_SHEET_URL):
    """Connect to the CIE Google Sheet using Streamlit Secrets/service-account JSON."""
    client = _gs_credentials(secret_value)
    return client.open_by_url(spreadsheet_url)

def _ensure_worksheet(sh, title, headers):
    try:
        ws = sh.worksheet(title)
    except Exception:
        ws = sh.add_worksheet(title=title, rows=max(1000, len(headers) + 10), cols=len(headers) + 5)
    current = ws.row_values(1)
    if current[:len(headers)] != headers:
        ws.update("A1", [headers])
    return ws

def _norm_db_text(value):
    if value is None:
        return ""
    return re.sub(r"\s+", " ", str(value).strip()).casefold()

def _split_exam_dates(value):
    """Normalize one date or a date range from the existing V1 Excel header."""
    raw = str(value or "").strip()
    if not raw:
        return "", ""

    def one(x):
        x = str(x).strip()
        for fmt in ("%d/%m/%Y", "%d-%m-%Y", "%Y-%m-%d", "%d.%m.%Y"):
            try:
                return datetime.datetime.strptime(x, fmt).date().isoformat()
            except ValueError:
                pass
        return x

    # Parse a complete single date first. This prevents ISO dates such as
    # 2026-09-28 from being mistaken for a date range.
    parsed_single = one(raw)
    if parsed_single != raw:
        return parsed_single, parsed_single

    # Only split when a real range separator is present.
    parts = re.split(r"\s+(?:-|–|—|đến|to)\s+", raw, maxsplit=1, flags=re.I)
    if len(parts) == 1:
        parts = re.split(r"(?:–|—|đến|to)", raw, maxsplit=1, flags=re.I)

    start = one(parts[0])
    end = one(parts[1]) if len(parts) == 2 else start
    return start, end

def _class_key(value):
    return re.sub(r"[^a-z0-9]+", "", _norm_db_text(value))

def _level_from_class(value):
    m = re.search(r"\b(LS|E|S|M|KET|PET|FCE|IELTS)\s*[- ]?\s*(\d+)\b", str(value or ""), re.I)
    return (m.group(1).upper() + m.group(2)) if m else str(value or "").strip()

def _record_key(name, class_name, exam_start, exam_end, assessment_type):
    raw = "|".join([_norm_db_text(name), _class_key(class_name), str(exam_start), str(exam_end), _norm_db_text(assessment_type)])
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:32]

def _new_student_id():
    return "STU-" + uuid.uuid4().hex[:12].upper()

def _history_from_worksheet(ws):
    values = ws.get_all_records()
    return [dict(row) for row in values if any(str(v).strip() for v in row.values())]

def load_google_history(db, include_status=False):
    """Read assessment history; by default only ACTIVE records feed analytics."""
    ws = _ensure_worksheet(db, GOOGLE_DB_SHEETS["assessments"], DB_ASSESSMENT_HEADERS)
    rows = _history_from_worksheet(ws)
    if include_status:
        return rows
    return [r for r in rows if str(r.get("status", "ACTIVE")).upper() == "ACTIVE"]

def _skill_value(student, skill_name):
    for sk in student.get("skills", []) or []:
        if _norm_db_text(sk.get("name")) == _norm_db_text(skill_name):
            return sk.get("band") if sk.get("band") is not None else sk.get("norm10")
    return ""

def _student_id_for(name, class_name, existing_students):
    name_key = _norm_db_text(name)
    matches = [r for r in existing_students if _norm_db_text(r.get("name_key") or r.get("name")) == name_key]
    if len(matches) == 1:
        return str(matches[0].get("student_id")), False
    if len(matches) > 1:
        # Same name has multiple profiles: do not silently merge.
        class_matches = [r for r in matches if _class_key(r.get("current_class")) == _class_key(class_name)]
        if len(class_matches) == 1:
            return str(class_matches[0].get("student_id")), False
        return None, True
    return _new_student_id(), False

def sync_students_to_google_sheet(db, students, source_file="", operator=""):
    """Upsert current student profiles and assessment records with duplicate protection."""
    sws = _ensure_worksheet(db, GOOGLE_DB_SHEETS["students"], DB_STUDENT_HEADERS)
    aws = _ensure_worksheet(db, GOOGLE_DB_SHEETS["assessments"], DB_ASSESSMENT_HEADERS)
    lws = _ensure_worksheet(db, GOOGLE_DB_SHEETS["audit"], DB_AUDIT_HEADERS)

    existing_students = _history_from_worksheet(sws)
    existing_assessments = _history_from_worksheet(aws)
    key_to_row = {}
    for idx, row in enumerate(existing_assessments, start=2):
        key = str(row.get("record_key", "")).strip()
        if key:
            key_to_row[key] = (idx, row)

    # De-duplicate the upload itself before touching Sheets.
    unique = {}
    duplicates_in_file = 0
    ambiguous = 0
    for st in students:
        ci = st.get("class_info") or {}
        start, end = _split_exam_dates(ci.get("ngay_thi"))
        key = _record_key(st.get("name"), ci.get("lop"), start, end, st.get("assessment_type", "Final"))
        if key in unique:
            duplicates_in_file += 1
            continue
        unique[key] = (st, start, end, key)

    now = datetime.datetime.now().isoformat(timespec="seconds")
    new_rows, changed_rows, existing_count = [], [], 0
    student_rows = {}
    upload_identity = {}

    for st, start, end, key in unique.values():
        ci = st.get("class_info") or {}
        name = st.get("name", "")
        class_name = ci.get("lop", "")
        name_key = _norm_db_text(name)

        # If a new upload contains the same name more than once, do not
        # silently assume that different classes are the same person.
        # Same name + same class may safely reuse the ID assigned in this upload.
        if name_key in upload_identity:
            prev_class, prev_sid = upload_identity[name_key]
            if _class_key(prev_class) != _class_key(class_name):
                ambiguous += 1
                continue
            sid, is_ambiguous = prev_sid, False
        else:
            sid, is_ambiguous = _student_id_for(name, class_name, existing_students)
            if not is_ambiguous:
                upload_identity[name_key] = (class_name, sid)

        if is_ambiguous:
            ambiguous += 1
            continue

        if not any(str(r.get("student_id")) == sid for r in existing_students):
            student_rows[sid] = [sid, name, _norm_db_text(name), now, now, ci.get("lop", ""), _level_from_class(ci.get("lop", "")), "ACTIVE"]
            existing_students.append(dict(zip(DB_STUDENT_HEADERS, student_rows[sid])))
        else:
            previous = next((r for r in existing_students if str(r.get("student_id")) == sid), {})
            student_rows[sid] = [sid, name, _norm_db_text(name), previous.get("first_seen", now), now, ci.get("lop", ""), _level_from_class(ci.get("lop", "")), "ACTIVE"]

        skills = {
            "listening": _skill_value(st, "Nghe"),
            "speaking": _skill_value(st, "Nói"),
            "reading": _skill_value(st, "Đọc"),
            "writing": _skill_value(st, "Viết"),
        }
        overall = st.get("overall", st.get("total", ""))
        row = [
            key, "ASM-" + uuid.uuid4().hex[:12].upper(), sid, name, _norm_db_text(name),
            ci.get("lop", ""), _class_key(ci.get("lop", "")), _level_from_class(ci.get("lop", "")),
            ci.get("giaovien", ""), ci.get("khoa_hoc", ""), "", start, end, st.get("assessment_type", "Final"),
            "ACTIVE", st.get("cc", ""), skills["listening"], skills["speaking"], skills["reading"], skills["writing"],
            overall if overall is not None else "", st.get("grade", ""), ", ".join(st.get("weak_skills", []) or []),
            source_file, 1, now, now
        ]
        if key not in key_to_row:
            new_rows.append(row)
        else:
            existing_count += 1
            idx, old = key_to_row[key]
            old_values = [old.get(h, "") for h in DB_ASSESSMENT_HEADERS]
            if old_values[2:25] != row[2:25]:
                changed_rows.append((idx, row))

    # IMPORTANT: Google Sheets has a per-user write-request quota.
    # Never call update()/append_row() once per student/record. Batch the writes.
    if student_rows:
        # Update existing profile rows by student_id; append genuinely new profiles.
        current_student_rows = _history_from_worksheet(sws)
        sid_to_row = {str(r.get("student_id")): i for i, r in enumerate(current_student_rows, start=2)}
        append_students = []
        student_updates = []
        for sid, row in student_rows.items():
            if sid in sid_to_row:
                student_updates.append({"range": f"A{sid_to_row[sid]}:H{sid_to_row[sid]}", "values": [row]})
            else:
                append_students.append(row)
        if student_updates:
            sws.batch_update(student_updates, value_input_option="USER_ENTERED")
        if append_students:
            sws.append_rows(append_students, value_input_option="USER_ENTERED")

    if new_rows:
        # One API request for the whole upload, not one request per student.
        aws.append_rows(new_rows, value_input_option="USER_ENTERED")

    if changed_rows:
        # Mark all replaced versions in one batch, then append all corrected ACTIVE rows
        # in one request. This avoids exhausting Sheets' Write requests/minute quota.
        status_updates = []
        replacement_rows = []
        for idx, row in changed_rows:
            status_updates.append({"range": f"O{idx}", "values": [["REPLACED"]]})
            row[1] = "ASM-" + uuid.uuid4().hex[:12].upper()
            row[24] = int(row[24]) + 1 if str(row[24]).isdigit() else 2
            replacement_rows.append(row)
        aws.batch_update(status_updates, value_input_option="USER_ENTERED")
        aws.append_rows(replacement_rows, value_input_option="USER_ENTERED")

    upload_id = "UP-" + uuid.uuid4().hex[:12].upper()
    audit = [upload_id, now, source_file, operator, len(students), len(new_rows), existing_count, len(changed_rows), duplicates_in_file, ambiguous]
    lws.append_row(audit, value_input_option="USER_ENTERED")
    return {
        "upload_id": upload_id, "total": len(students), "new": len(new_rows),
        "existing": existing_count, "changed": len(changed_rows),
        "duplicates_in_file": duplicates_in_file, "ambiguous": ambiguous,
    }

def process_and_sync_workbook(path, secret_value, assessment_type="Final", spreadsheet_url=GOOGLE_SHEET_URL, operator=""):
    """Full V2 flow: read history -> run V1 parser -> analyze -> deduplicate -> save to Sheets."""
    db = get_google_database(secret_value, spreadsheet_url)
    history = load_google_history(db)
    students = process_workbook(path, history=history, assessment_type=assessment_type)
    result = sync_students_to_google_sheet(db, students, source_file=str(path), operator=operator)
    return students, result


