GRADE_ORDER = ["A+", "A", "B+", "B", "C+", "C", "D"]

def grade_from_total(total):
    if total >= 97.5: return "A+"
    if total >= 94.5: return "A"
    if total >= 89.5: return "B+"
    if total >= 79.5: return "B"
    if total >= 74.5: return "C+"
    if total >= 64.5: return "C"
    return "D"

