def ielts_band_bucket(overall):
    for upper, key, label, items, kn in IELTS_BANDS:
        if overall < upper:
            return {"key": key, "label": label, "items": items, "kien_nghi": kn}
    k = IELTS_BANDS[-1]
    return {"key": k[1], "label": k[2], "items": k[3], "kien_nghi": k[4]}

