E_CLASS = {
 "A+": {"label": "Tốt", "items": _E_ITEMS_TOT, "kien_nghi": _E_KN["A+"]},
 "A": {"label": "Tốt", "items": _E_ITEMS_TOT, "kien_nghi": _E_KN["A"]},
 "B+": {"label": "Khá", "items": _E_ITEMS_KHA, "kien_nghi": _E_KN["B+"]},
 "B": {"label": "Khá", "items": _E_ITEMS_KHA, "kien_nghi": _E_KN["B"]},
 "C+": {"label": "Trung bình", "items": _E_ITEMS_TB, "kien_nghi": _E_KN["C+"]},
 "C": {"label": "Trung bình", "items": _E_ITEMS_TB, "kien_nghi": _E_KN["C"]},
 "D": {"label": "Yếu", "items": _E_ITEMS_YEU, "kien_nghi": _E_KN["D"]},
}

import re

SKILL_PAT = re.compile(r'^(.*?)\n.*?\((\d+(?:\.\d+)?)%\)\s*$', re.S)
MAX_PAT = re.compile(r'\((\d+(?:\.\d+)?)\)')
CC_PAT = re.compile(r'Chuyên cần.*?\((\d+(?:\.\d+)?)%\)', re.S)

def find_header_row(ws, max_scan=40):
    for r in range(1, min(max_scan, ws.max_row) + 1):
        for c in range(1, ws.max_column + 1):
            v = ws.cell(r, c).value
            if v and str(v).strip().startswith('STT'):
                return r
    return None

def col_text(ws, r, c):
    v = ws.cell(r, c).value
    return str(v) if v is not None else ''

def is_cc_sheet(sheet_name):
    return bool(re.match(r'^\s*\d+\.\s*CC\s', sheet_name))

def detect_sheet_kind(ws, hdr_row):
    row_text = ' '.join(col_text(ws, hdr_row, c) for c in range(1, ws.max_column + 1))
    row_text += ' ' + ' '.join(col_text(ws, hdr_row + 1, c) for c in range(1, ws.max_column + 1))
    if 'OVERALL BAND SCORE' in row_text.upper() or 'Band score' in row_text:
        return 'ielts'
    return 'standard'

def parse_cc_sheet(ws, hdr_row):
    # header spans hdr_row, hdr_row+1 ; data starts hdr_row+2 typically (numbers row) -> hdr_row+3
    ncols = ws.max_column
    layout = {'stt': None, 'ten': None, 'tong_col': None,
              'kyluat_col': None, 'diemdanh_col': None, 'btvn_col': None, 'hoatdong_col': None}
    for c in range(1, ncols + 1):
        t = col_text(ws, hdr_row, c)
        if t.strip().startswith('STT'):
            layout['stt'] = c
        if 'học viên' in t.lower() and 'tên' in t.lower():
            layout['ten'] = c
        t2 = col_text(ws, hdr_row + 1, c)
        if 'Tổng cộng' in t2:
            layout['tong_col'] = c
        if 'Kỷ luật' in t2:
            layout['kyluat_col'] = c
        if 'Điểm danh' in t2:
            layout['diemdanh_col'] = c
        if 'Bài tập về nhà' in t2 or 'BTVN' in t2:
            layout['btvn_col'] = c
        if 'Hoạt động' in t2:
            layout['hoatdong_col'] = c
    data_start = hdr_row + 3  # skip the "1,2,3.." index row
    return layout, data_start

def parse_standard_sheet(ws, hdr_row):
    r1, r2, r3 = hdr_row, hdr_row + 1, hdr_row + 2
    ncols = ws.max_column
    layout = {'stt': None, 'ten': None, 'cc_col': None, 'cc_weight': None,
              'skills': [], 'tong_col': None, 'kyhieu_col': None, 'xeploai_col': None, 'ghichu_col': None}
    for c in range(1, ncols + 1):
        t1 = col_text(ws, r1, c)
        if t1.strip().startswith('STT'):
            layout['stt'] = c
        if t1.strip().startswith('Tên'):
            layout['ten'] = c
        m = CC_PAT.search(t1)
        if m:
            layout['cc_col'] = c
            layout['cc_weight'] = float(m.group(1))
        if 'Tổng điểm' in t1 or 'Total score' in t1:
            layout['tong_col'] = c
        if 'Ghi chú' in t1:
            layout['ghichu_col'] = c
    for c in range(1, ncols + 1):
        t2 = col_text(ws, r2, c)
        m = SKILL_PAT.match(t2)
        if m:
            name_vn = m.group(1).strip()
            weight = float(m.group(2))
            t3 = col_text(ws, r3, c)
            mm = MAX_PAT.search(t3)
            max_score = float(mm.group(1)) if mm else None
            layout['skills'].append({'name': name_vn, 'weight': weight, 'max': max_score, 'col': c})
    for c in range(1, ncols + 1):
        t3 = col_text(ws, r3, c)
        if 'Ký hiệu' in t3:
            layout['kyhieu_col'] = c
        if t3.strip() == 'Xếp loại':
            layout['xeploai_col'] = c
    return layout, r3 + 1

def parse_ielts_sheet(ws, hdr_row):
    r1, r2, r3 = hdr_row, hdr_row + 1, hdr_row + 2
    ncols = ws.max_column
    layout = {'stt': None, 'ten': None, 'skills': [], 'overall_col': None, 'ghichu_col': None}
    for c in range(1, ncols + 1):
        t1 = col_text(ws, r1, c)
        if t1.strip().startswith('STT'):
            layout['stt'] = c
        if t1.strip().startswith('Tên'):
            layout['ten'] = c
        if 'OVERALL BAND' in t1.upper():
            layout['overall_col'] = c
        if 'Ghi chú' in t1:
            layout['ghichu_col'] = c
    for c in range(1, ncols + 1):
        t3 = col_text(ws, r3, c).strip()
        if t3 == 'Band score':
            # find nearest skill label scanning left in row r2
            name = None
            for back in range(0, 5):
                cc = c - back
                if cc < 1:
                    break
                t2 = col_text(ws, r2, cc).strip()
                if t2:
                    name = t2.split('\n')[0].strip()
                    break
            layout['skills'].append({'name': name, 'band_col': c})
    return layout, r3 + 2  # skip the extra "1,2,3.." position-index filler row

def _num(v):
    try:
        if v is None or v == '':
            return None
        return float(v)
    except (TypeError, ValueError):
        return None

def build_cc_lookup(wb_v, cc_sheet_name):
    ws = wb_v[cc_sheet_name]
    hdr = find_header_row(ws)
    layout, data_start = parse_cc_sheet(ws, hdr)
    lut = {}
    r = data_start
    blanks = 0
    while r <= ws.max_row and blanks < 3:
        name = ws.cell(r, layout['ten']).value if layout['ten'] else None
        if name is None or str(name).strip() == '':
            blanks += 1
            r += 1
            continue
        blanks = 0
        tong = _num(ws.cell(r, layout['tong_col']).value) if layout['tong_col'] else None
        entry = {'tong': tong}
        for key in ('kyluat_col', 'diemdanh_col', 'btvn_col', 'hoatdong_col'):
            col = layout.get(key)
            entry[key.replace('_col', '')] = _num(ws.cell(r, col).value) if col else None
        lut[str(name).strip().upper()] = entry
        r += 1
    return lut

def extract_standard(wb_f, wb_v, sheet_name, class_info, cc_lookup=None):
    ws_f = wb_f[sheet_name]
    ws_v = wb_v[sheet_name]
    hdr = find_header_row(ws_f)
    layout, data_start = parse_standard_sheet(ws_f, hdr)
    students = []
    r = data_start
    blanks = 0
    while r <= ws_v.max_row and blanks < 3:
        name = ws_v.cell(r, layout['ten']).value if layout['ten'] else None
        stt_val = _num(ws_v.cell(r, layout['stt']).value) if layout['stt'] else None
        if name is None or str(name).strip() == '' or stt_val is None:
            blanks += 1
            r += 1
            continue
        blanks = 0
        name = str(name).strip()
        cc_val = _num(ws_v.cell(r, layout['cc_col']).value) if layout['cc_col'] else None
        cc_breakdown = None
        if cc_lookup is not None:
            entry = cc_lookup.get(name.upper())
            if entry:
                cc_breakdown = entry
                if cc_val is None:
                    cc_val = entry.get('tong')
        if cc_val is None:
            cc_val = 0.0

        # Neu sheet Chuyen can khong co / khong co du lieu chi tiet (Ky luat, Diem danh, BTVN, Hoat dong
        # deu rong) -> "tinh nguoc" bang cach dung diem Chuyen can tong o file chinh cho ca 4 muc con,
        # de bang 1 tren phieu luon co du liệu hien thi thay vi de trong.
        breakdown_missing = (cc_breakdown is None) or all(
            cc_breakdown.get(k) is None for k in ('kyluat', 'diemdanh', 'btvn', 'hoatdong')
        )
        if breakdown_missing:
            cc_breakdown = {'kyluat': cc_val, 'diemdanh': cc_val, 'btvn': cc_val, 'hoatdong': cc_val, 'tong': cc_val}

        skills = []
        for sk in layout['skills']:
            raw = _num(ws_v.cell(r, sk['col']).value)
            maxv = sk['max'] or 10.0
            if raw is None:
                # Khong co diem = None, khong phai 0.
                skills.append({'name': sk['name'], 'raw': None, 'max': maxv, 'weight': sk['weight'],
                                'pct_contrib': None, 'norm10': None})
            else:
                pct_contrib = round((raw / maxv) * sk['weight'], 1) if maxv else 0.0
                normalized10 = round((raw / maxv) * 10, 2) if maxv else 0.0
                skills.append({'name': sk['name'], 'raw': raw, 'max': maxv, 'weight': sk['weight'],
                                'pct_contrib': pct_contrib, 'norm10': normalized10})

        # Neu thieu diem o bat ky ky nang nao: KHONG tinh lai tong/xep loai.
        # Chi danh dau hoc vien chua du du lieu de tinh ket qua cuoi khoa.
        available = [s for s in skills if s['raw'] is not None]
        missing_skills = [s['name'] for s in skills if s['raw'] is None]
        if missing_skills:
            total = None
            grade = 'Chưa đủ dữ liệu điểm số, yêu cầu cập nhật lại điểm số'
        else:
            cached_tong = _num(ws_v.cell(r, layout['tong_col']).value) if layout['tong_col'] else None
            test_contrib = sum(s['pct_contrib'] for s in available)
            if cached_tong is not None:
                total = cached_tong
            else:
                total = round(test_contrib + cc_val, 1)
            cached_grade = ws_v.cell(r, layout['kyhieu_col']).value if layout['kyhieu_col'] else None
            grade = cached_grade.strip() if isinstance(cached_grade, str) and cached_grade.strip() else grade_from_total(total)

        # Chi danh gia ky nang co diem. Ky nang 'Chua co diem' khong duoc xem la ky nang yeu.
        weak = []
        if len(available) >= 2:
            norms = [s['norm10'] for s in available]
            for s in available:
                others_avg = (sum(norms) - s['norm10']) / (len(norms) - 1)
                if s['norm10'] < 6 and s['norm10'] <= others_avg - 1:
                    weak.append(s['name'])

        students.append({
            'name': name, 'type': 'standard', 'class_info': class_info,
            'cc': cc_val, 'cc_weight': layout.get('cc_weight') or 10.0, 'cc_breakdown': cc_breakdown,
            'skills': skills, 'total': total, 'grade': grade,
            'weak_skills': weak,
        })
        r += 1
    return students

def extract_ielts(wb_f, wb_v, sheet_name, class_info):
    ws_f = wb_f[sheet_name]
    ws_v = wb_v[sheet_name]
    hdr = find_header_row(ws_f)
    layout, data_start = parse_ielts_sheet(ws_f, hdr)
    students = []
    r = data_start
    blanks = 0
    while r <= ws_v.max_row and blanks < 3:
        name = ws_v.cell(r, layout['ten']).value if layout['ten'] else None
        stt_val = _num(ws_v.cell(r, layout['stt']).value) if layout['stt'] else None
        if name is None or str(name).strip() == '' or stt_val is None:
            blanks += 1
            r += 1
            continue
        blanks = 0
        name = str(name).strip()
        skills = []
        for sk in layout['skills']:
            band = _num(ws_v.cell(r, sk['band_col']).value)
            skills.append({'name': sk['name'], 'band': band})
        available = [s for s in skills if s['band'] is not None]
        missing_skills = [s['name'] for s in skills if s['band'] is None]
        cached_overall = _num(ws_v.cell(r, layout['overall_col']).value) if layout['overall_col'] else None
        # Neu thieu bat ky ky nang nao: khong tinh lai Overall.
        # Ket qua se thong bao chua du du lieu va yeu cau cap nhat diem.
        if missing_skills:
            overall = None
        elif cached_overall is not None:
            overall = cached_overall
        elif available:
            overall = round(sum(s['band'] for s in available) / len(available), 1)
        else:
            overall = None

        # Chi danh gia ky nang co diem.
        weak = []
        if len(available) >= 2:
            bands = [s['band'] for s in available]
            for s in available:
                others_avg = (sum(bands) - s['band']) / (len(bands) - 1)
                if s['band'] < 5.0 and s['band'] <= others_avg - 1.0:
                    weak.append(s['name'])

        students.append({
            'name': name, 'type': 'ielts', 'class_info': class_info,
            'skills': skills, 'overall': overall, 'weak_skills': weak,
        })
        r += 1
    return students

def process_workbook(path, history=None, assessment_type='Final'):
    """V1 workbook parser with optional historical-development analysis.

    `history` is optional and is intentionally read-only: current scores always
    come exclusively from the uploaded workbook.
    """
    wb_f = openpyxl.load_workbook(path, data_only=False)
    wb_v = openpyxl.load_workbook(path, data_only=True)
    all_students = []
    sheet_names = wb_f.sheetnames
    for name in sheet_names:
        if is_cc_sheet(name):
            continue
        ws = wb_f[name]
        hdr = find_header_row(ws)
        if hdr is None:
            continue
        # class info from rows above header (Lop/Giao vien/Khoa hoc)
        class_info = {'sheet': name, 'lop': None, 'giaovien': None, 'ngay_thi': None}
        for rr in range(1, hdr):
            v = ws.cell(rr, 1).value
            if v and isinstance(v, str):
                if v.strip().startswith('Lớp'):
                    class_info['lop'] = v.split(':', 1)[-1].strip()
                if v.strip().startswith('Giáo viên'):
                    class_info['giaovien'] = v.split(':', 1)[-1].strip()
                if v.strip().startswith('Ngày thi'):
                    class_info['ngay_thi'] = v.split(':', 1)[-1].strip()
        kind = detect_sheet_kind(ws, hdr)
        if kind == 'standard':
            cc_sheet_guess = re.sub(r'^(\s*\d+\.\s*)', r'\1CC ', name)
            cc_lookup = None
            if cc_sheet_guess in sheet_names:
                cc_lookup = build_cc_lookup(wb_v, cc_sheet_guess)
            all_students.extend(extract_standard(wb_f, wb_v, name, class_info, cc_lookup))
        else:
            all_students.extend(extract_ielts(wb_f, wb_v, name, class_info))
    # Gán loại đánh giá trước khi phân tích lịch sử.
    # Initial/Placement là mốc đánh giá đầu vào/định vị, không được đem
    # so với dữ liệu cũ. Các lần upload đầu tiên cũng không được so sánh
    # với những record thử nghiệm không có điểm (0/blank).
    for student in all_students:
        student['assessment_type'] = assessment_type
        if assessment_type in ('Initial', 'Placement'):
            student['development'] = empty_development()
        elif history:
            student['development'] = analyze_development(student, history)
        else:
            student['development'] = empty_development()
    return all_students

# ---- V2: Phan tich phat trien - ke thua truc tiep cac tieu chi V1 ----
# Luu y: ham nay KHONG thay doi cach tinh diem/xep loai/weak_skills cua V1.
# No chi doc lich su de tao thong tin phat trien cho bao cao hien tai.

HISTORY_SKILL_ALIASES = {
    'nghe': 'Nghe', 'listening': 'Nghe', 'l': 'Nghe',
    'nói': 'Nói', 'noi': 'Nói', 'speaking': 'Nói', 's': 'Nói',
    'đọc': 'Đọc', 'doc': 'Đọc', 'reading': 'Đọc', 'r': 'Đọc',
    'viết': 'Viết', 'viet': 'Viết', 'writing': 'Viết', 'w': 'Viết',
}

def _norm_name_v2(value):
    if value is None:
        return ''
    return re.sub(r'\s+', ' ', str(value).strip()).casefold()

def _history_skills(record):
    """Extract skill values from common DB shapes without changing V1 data."""
    out = {}
    skills = record.get('skills') if isinstance(record, dict) else None
    if isinstance(skills, list):
        for sk in skills:
            if not isinstance(sk, dict):
                continue
            name = HISTORY_SKILL_ALIASES.get(_norm_name_v2(sk.get('name')), sk.get('name'))
            value = sk.get('norm10')
            if value is None:
                value = sk.get('band')
            if value is None:
                raw, maxv = sk.get('raw'), sk.get('max')
                if raw is not None and maxv:
                    try:
                        value = float(raw) / float(maxv) * 10
                    except Exception:
                        value = None
            try:
                if value is not None:
                    out[str(name)] = float(value)
            except Exception:
                pass
    # Google Sheets-friendly flat columns are also accepted.
    for key, canonical in HISTORY_SKILL_ALIASES.items():
        if canonical in out:
            continue
        for candidate in (key, key.title(), canonical, canonical.lower()):
            if isinstance(record, dict) and candidate in record and record[candidate] not in (None, ''):
                try:
                    out[canonical] = float(record[candidate])
                except Exception:
                    pass
                break
    return out

def _current_skills(student):
    out = {}
    for sk in student.get('skills', []):
        try:
            if student.get('type') == 'ielts':
                value = sk.get('band')
            else:
                value = sk.get('norm10')
            if value is not None:
                out[str(sk.get('name'))] = float(value)
        except Exception:
            pass
    return out

def empty_development():
    return {
        'history_count': 0,
        'baseline': None,
        'previous': None,
        'trend': None,
        'skill_changes': {},
        'strong_skills': [],
        'priority_skills': [],
        'summary': None,
    }

def analyze_development(student, history):
    """Create a factual development summary from prior records.

    V1's weak_skills remains authoritative for the current assessment.
    Historical data is used only to explain progress and persistence of gaps.
    Records with the same current assessment are excluded from the historical
    comparison when an assessment key is available.
    """
    result = empty_development()
    if not isinstance(history, (list, tuple)):
        return result

    name_key = _norm_name_v2(student.get('name'))
    class_key = _norm_name_v2((student.get('class_info') or {}).get('lop'))
    current_date = _norm_name_v2((student.get('class_info') or {}).get('ngay_thi'))
    rows = []
    for rec in history:
        if not isinstance(rec, dict) or _norm_name_v2(rec.get('name')) != name_key:
            continue
        rskills = _history_skills(rec)
        if not rskills:
            continue

        # Không dùng các record thử nghiệm/record rỗng có toàn bộ điểm = 0.
        # Đây là nguyên nhân thường gặp khiến lần upload đầu tiên bị báo
        # 'tăng từ 0 điểm' dù thực tế học viên chưa có lịch sử hợp lệ.
        overall_raw = rec.get('overall', rec.get('total'))
        try:
            overall_num = float(overall_raw) if overall_raw not in (None, '') else None
        except Exception:
            overall_num = None
        numeric_skill_values = [v for v in rskills.values() if isinstance(v, (int, float))]
        if numeric_skill_values and all(float(v) == 0 for v in numeric_skill_values) and (overall_num in (None, 0.0)):
            continue
        # Do not use current record as history if the caller accidentally passes it.
        if _norm_name_v2(rec.get('ngay_thi')) == current_date and _norm_name_v2(rec.get('lop')) == class_key:
            continue
        total = rec.get('overall', rec.get('total'))
        try:
            total = float(total) if total not in (None, '') else None
        except Exception:
            total = None
        rows.append({
            'date': str(rec.get('ngay_thi') or rec.get('exam_start') or ''),
            'lop': rec.get('lop') or rec.get('class') or '',
            'assessment_type': rec.get('assessment_type') or rec.get('loai_danh_gia') or '',
            'skills': rskills,
            'overall': total,
        })
    if not rows:
        return result

    # Preserve supplied chronological order when dates are not machine-readable.
    rows.sort(key=lambda x: x.get('date') or '')
    result['history_count'] = len(rows)
    result['baseline'] = rows[0]
    result['previous'] = rows[-1]

    current = _current_skills(student)
    previous = rows[-1]['skills']
    common = [k for k in current if k in previous]
    for sk in common:
        result['skill_changes'][sk] = round(current[sk] - previous[sk], 2)

    if student.get('type') == 'ielts':
        current_total = student.get('overall')
    else:
        current_total = student.get('total')
    try:
        prev_total = rows[-1].get('overall')
        if current_total is not None and prev_total is not None:
            result['trend'] = round(float(current_total) - float(prev_total), 2)
    except Exception:
        pass

    # V1 weak_skills remains the first source for current priorities.
    result['priority_skills'] = list(student.get('weak_skills') or [])
    if not result['priority_skills'] and result['skill_changes']:
        # Only use historical decline as a supplemental signal; never overwrite V1.
        declining = [k for k, d in result['skill_changes'].items() if d < 0]
        result['priority_skills'] = declining

    # Strong skills are descriptive, not a new scoring system.
    if current:
        avg = sum(current.values()) / len(current)
        result['strong_skills'] = [k for k, v in current.items() if v >= avg]

    if result['trend'] is not None:
        if result['trend'] > 0:
            result['summary'] = f"Kết quả hiện tại tăng {result['trend']:.1f} điểm so với lần đánh giá trước có dữ liệu phù hợp."
        elif result['trend'] < 0:
            result['summary'] = f"Kết quả hiện tại giảm {abs(result['trend']):.1f} điểm so với lần đánh giá trước có dữ liệu phù hợp."
        else:
            result['summary'] = "Kết quả hiện tại duy trì tương đương lần đánh giá trước có dữ liệu phù hợp."
    return result

BRAND = RGBColor(0x1F, 0x4E, 0x79)
RED = RGBColor(0xC0, 0x00, 0x00)
COMPANY_LOGO_PATH = None  # default logo; can be overridden per build_phieu(..., logo_path=...)

def set_logo_path(path):
    """Set the default logo path for backwards-compatible V1 callers."""
    global COMPANY_LOGO_PATH
    COMPANY_LOGO_PATH = path

LEGEND_LEFT = ["A+   Outstanding (Xuất sắc): 98 – 100", "A     Excellent (Rất giỏi): 95 - 97", "B+   Very good (Giỏi): 90 – 94"]
LEGEND_RIGHT = ["B     Good (Khá): 80 - 89", "C+   Average (Trung bình): 75 - 79", "C     Need improvement (Cần cố gắng hơn): 65 - 74", "D     Fail (Không đạt) < 65"]


def _shade(cell, hex_color):
    shd = OxmlElement('w:shd')
    shd.set(qn('w:fill'), hex_color)
    cell._tc.get_or_add_tcPr().append(shd)


def _vcenter(cell):
    cell.vertical_alignment = WD_ALIGN_VERTICAL.CENTER


def _set_cell_text(cell, text, bold=False, italic=False, size=10.5, align=WD_ALIGN_PARAGRAPH.LEFT, color=None):
    cell.text = ''
    p = cell.paragraphs[0]
    p.alignment = align
    lines = str(text).split('\n')
    for i, line in enumerate(lines):
        if i > 0:
            p.add_run().add_break()
        r = p.add_run(line)
        r.bold = bold
        r.italic = italic
        r.font.size = Pt(size)
        if color:
            r.font.color.rgb = color
    _vcenter(cell)
    return cell


def _merge_col_widths(table, widths_cm):
    for row in table.rows:
        for idx, w in enumerate(widths_cm):
            row.cells[idx].width = Cm(w)


def _section_title_row(table, row_idx, text, ncols, size=11):
    row = table.rows[row_idx]
    a = row.cells[0]
    for i in range(1, ncols):
        a = a.merge(row.cells[i])
    _set_cell_text(a, text, bold=True, size=size, align=WD_ALIGN_PARAGRAPH.LEFT)
    _shade(a, 'D9E2F3')


def _add_logo_header(doc):
    """Chèn logo vào header của document -> tự động lặp lại trên MỌI trang,
    kể cả các trang được thêm sau này (Nhận xét, v.v.), và không bị thay thế khi nội dung thay đổi."""
    if not COMPANY_LOGO_PATH:
        return
    section = doc.sections[0]
    section.header.is_linked_to_previous = False
    # xoa noi dung header cu (neu co) va chen logo
    header_p = section.header.paragraphs[0]
    header_p.text = ''
    header_p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = header_p.add_run()
    try:
        run.add_picture(COMPANY_LOGO_PATH, width=Cm(2.6))
    except Exception:
        pass


def _add_logo_and_title(doc):
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r = p.add_run("BÁO CÁO KẾT QUẢ HỌC TẬP CUỐI KHÓA")
    r.bold = True
    r.font.size = Pt(16)
    p.paragraph_format.space_after = Pt(0)

    p2 = doc.add_paragraph()
    p2.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r2 = p2.add_run("(FINAL COURSE REPORT)")
    r2.bold = True
    r2.italic = True
    r2.font.size = Pt(13)
    p2.paragraph_format.space_after = Pt(10)


