def get_logo_b64(logo_name):
    name = str(logo_name).strip().upper()
    if name == "SIT":
        return DEFAULT_SIT_LOGO_B64
    if name == "CIE":
        return DEFAULT_CIE_LOGO_B64
    raise ValueError("Logo không hợp lệ. Chỉ cho phép SIT hoặc CIE.")


